begin;
create extension if not exists pgtap with schema extensions;
select plan(37);
insert into auth.users(id,email) values
 ('90000000-0000-0000-0000-000000000001','study-teacher@example.test'),
 ('90000000-0000-0000-0000-000000000002','study-student@example.test'),
 ('90000000-0000-0000-0000-000000000003','study-other@example.test');
update lms.profiles set role='teacher' where id='90000000-0000-0000-0000-000000000001';
update lms.profiles set assessment_completed=true where role='student';
insert into lms.courses(id,title,teacher_id,published) values('91000000-0000-0000-0000-000000000001','Study','90000000-0000-0000-0000-000000000001',true);
insert into lms.enrollments select '91000000-0000-0000-0000-000000000001',id,'approved' from lms.profiles where id in ('90000000-0000-0000-0000-000000000002','90000000-0000-0000-0000-000000000003');
set local role authenticated;
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000001',true);
select lms.save_lesson('{"id":"92000000-0000-0000-0000-000000000001","course_id":"91000000-0000-0000-0000-000000000001","title":"Study","position":1,"published":true,"content":[{"id":"visual","styles":["visual"],"blocks":[{"id":"text","type":"text","text":"Read"},{"id":"single","type":"practice","text":"Choose B","activity":{"type":"single","options":["A","B"],"answer":1}},{"id":"order","type":"practice","text":"Reverse","activity":{"type":"ordering","options":["A","B"],"answer":["B","A"]}}]},{"id":"audio","styles":["auditory"],"blocks":[{"id":"legacy","type":"practice","text":"Practice"}]}],"questions":[{"id":"q","type":"single","prompt":"Choose","options":["A","B"],"answer":0}]}');
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000002',true);
select throws_ok($$select lms.start_attempt('92000000-0000-0000-0000-000000000001')$$,'42501','Complete lesson material first','attempt blocked without study');
select throws_ok($$select lms.create_study_session('92000000-0000-0000-0000-000000000001','missing')$$,'P0001','Variant unavailable','unknown variant rejected');
select set_config('study.id',(lms.create_study_session('92000000-0000-0000-0000-000000000001','visual')->>'id'),true);
select throws_ok($$select lms.start_attempt('92000000-0000-0000-0000-000000000001',false,current_setting('study.id')::uuid)$$,'42501','Complete lesson material first','unread session blocked');
select throws_ok($$select lms.record_study_block(current_setting('study.id')::uuid,'single','1')$$,'P0001','Read blocks in order','cannot jump to practice');
select throws_ok($$select lms.record_study_block(current_setting('study.id')::uuid,'unknown')$$,'P0001','Unknown study block','unknown block rejected');
select is(lms.record_study_block(current_setting('study.id')::uuid,'text')->'completed_blocks','["text"]'::jsonb,'text explicitly acknowledged');
select throws_ok($$select lms.start_attempt('92000000-0000-0000-0000-000000000001',false,current_setting('study.id')::uuid)$$,'42501','Complete lesson material first','partly read session blocked');
select throws_ok($$select lms.record_study_block(current_setting('study.id')::uuid,'single','0')$$,'P0001','Incorrect practice answer','incorrect single answer blocked');
select is((lms.record_study_block(current_setting('study.id')::uuid,'single','1')->>'completed')::boolean,false,'correct single advances');
select throws_ok($$select lms.record_study_block(current_setting('study.id')::uuid,'order','["A","B"]')$$,'P0001','Incorrect practice answer','incorrect ordering blocked');
select is((lms.record_study_block(current_setting('study.id')::uuid,'order','["B","A"]')->>'completed')::boolean,true,'correct ordering completes material');
select is(lms.record_study_block(current_setting('study.id')::uuid,'text')->'completed_blocks','["text","single","order"]'::jsonb,'completed session remains unchanged');
select set_config('study.attempt',lms.start_attempt('92000000-0000-0000-0000-000000000001',false,current_setting('study.id')::uuid)::text,true);
select is((lms.submit_attempt(current_setting('study.attempt')::uuid,'{"q":1}')->>'passed')::boolean,false,'completed study allows failed test');
select lives_ok($$select lms.start_attempt('92000000-0000-0000-0000-000000000001',false,current_setting('study.id')::uuid)$$,'retry may reuse completed study');
select set_config('study.other',(lms.create_study_session('92000000-0000-0000-0000-000000000001','audio')->>'id'),true);
select isnt(current_setting('study.other'),current_setting('study.id'),'switching variant creates fresh session');
select throws_ok($$select lms.start_attempt('92000000-0000-0000-0000-000000000001',false,current_setting('study.other')::uuid)$$,'42501','Complete lesson material first','new variant requires own completion');
select is((lms.record_study_block(current_setting('study.other')::uuid,'legacy')->>'completed')::boolean,true,'legacy practice is acknowledgable');
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000003',true);
select is((select count(*)::integer from lms.study_sessions),0,'session RLS hides other students');
select throws_ok($$select lms.record_study_block(current_setting('study.id')::uuid,'text')$$,'42501','Study unavailable','cannot record someone else session');
select throws_ok($$select lms.start_attempt('92000000-0000-0000-0000-000000000001',false,current_setting('study.id')::uuid)$$,'42501','Complete lesson material first','cannot use someone else completed study');
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000001',true);
select set_config('study.preview',(lms.create_study_session('92000000-0000-0000-0000-000000000001','audio',true)->>'id'),true);
select lms.record_study_block(current_setting('study.preview')::uuid,'legacy');
select lives_ok($$select lms.start_attempt('92000000-0000-0000-0000-000000000001',true,current_setting('study.preview')::uuid)$$,'teacher preview study allows preview attempt');
select throws_ok($$select lms.start_attempt('92000000-0000-0000-0000-000000000001',false,current_setting('study.preview')::uuid)$$,'42501','Invalid attempt mode','preview completion cannot create student attempt');
reset role;
insert into lms.attempts(id,student_id,lesson_id,revision_id) select '93000000-0000-0000-0000-000000000001','90000000-0000-0000-0000-000000000002',id,current_revision_id from lms.lessons where id='92000000-0000-0000-0000-000000000001';
insert into lms.attempts(id,student_id,lesson_id,revision_id,submitted_at,score,total,percentage,passed) select '93000000-0000-0000-0000-000000000002','90000000-0000-0000-0000-000000000002',id,current_revision_id,now(),1,1,100,true from lms.lessons where id='92000000-0000-0000-0000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000002',true);
select throws_ok($$select lms.submit_attempt('93000000-0000-0000-0000-000000000001','{"q":0}')$$,'42501','Complete lesson material first','unsubmitted historical attempt cannot bypass gate');
select is((lms.submit_attempt('93000000-0000-0000-0000-000000000002','{}')->>'passed')::boolean,true,'submitted historical attempt retains result');
select throws_ok($$update lms.study_sessions set completed_at=now()$$,'42501',null,'clients cannot forge completion');
select throws_ok($$insert into lms.study_sessions(student_id,lesson_id,revision_id,variant_id) values(auth.uid(),'92000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000001','visual')$$,'42501',null,'clients cannot forge sessions');
select set_config('study.fresh',(lms.create_study_session('92000000-0000-0000-0000-000000000001','visual')->>'id'),true);
select isnt(current_setting('study.fresh'),current_setting('study.id'),'same variant also starts fresh session');
select is((select cardinality(completed_blocks) from lms.study_sessions where id=current_setting('study.fresh')::uuid),0,'fresh study never inherits completion');
select throws_ok($$select lms.start_attempt('92000000-0000-0000-0000-000000000001',true,current_setting('study.id')::uuid)$$,'42501','Invalid attempt mode','student cannot use preview mode');
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000001',true);
select lives_ok($$select lms.save_lesson('{"course_id":"91000000-0000-0000-0000-000000000001","title":"Incomplete practice","position":2,"content":[{"id":"v","styles":["visual"],"blocks":[{"id":"b","type":"practice","text":"","activity":{"type":"single","options":["",""],"answer":0}}]}]}')$$,'incomplete practice draft can be saved');
select throws_ok($$select lms.save_lesson('{"published":true,"course_id":"91000000-0000-0000-0000-000000000001","title":"Bad practice","position":3,"content":[{"id":"v","styles":["visual"],"blocks":[{"id":"b","type":"practice","text":"Choose","activity":{"type":"single","options":["A","B"],"answer":9}}]}]}')$$,'P0001','Invalid practice activity','malformed training key rejected on publish');
select throws_ok($$select lms.save_lesson('{"published":true,"course_id":"91000000-0000-0000-0000-000000000001","title":"Bad ordering","position":3,"content":[{"id":"v","styles":["visual"],"blocks":[{"id":"b","type":"practice","text":"Order","activity":{"type":"ordering","options":["A","B"],"answer":["A","A"]}}]}]}')$$,'P0001','Invalid practice activity','ordering practice must be a permutation');
select throws_ok($$select lms.save_lesson('{"published":true,"course_id":"91000000-0000-0000-0000-000000000001","title":"Bad activity","position":3,"content":[{"id":"v","styles":["visual"],"blocks":[{"id":"b","type":"text","text":"Read","activity":{"type":"single","options":["A","B"],"answer":0}}]}]}')$$,'P0001','Invalid practice activity','only practice blocks accept activities');
select throws_ok($$select lms.save_lesson_base('{}')$$,'42501',null,'base lesson writer is private');
reset role;
insert into lms.revisions(id,lesson_id,title,position,content,questions) select '94000000-0000-0000-0000-000000000001',lesson_id,'New',position,content,questions from lms.revisions where id=(select current_revision_id from lms.lessons where id='92000000-0000-0000-0000-000000000001');
update lms.lessons set current_revision_id='94000000-0000-0000-0000-000000000001' where id='92000000-0000-0000-0000-000000000001';
set local role authenticated;
select throws_ok($$select lms.start_attempt('92000000-0000-0000-0000-000000000001',true,current_setting('study.preview')::uuid)$$,'42501','Complete lesson material first','preview session cannot unlock a changed revision');
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000002',true);
select lives_ok($$select lms.start_attempt('92000000-0000-0000-0000-000000000001',false,current_setting('study.id')::uuid)$$,'student study stays usable on pinned revision after publication');
set local role anon;
select throws_ok($$select lms.create_study_session('92000000-0000-0000-0000-000000000001','visual')$$,'42501',null,'guest cannot create sessions');
select * from finish();
rollback;
